#!/usr/bin/env bash
# ep91 final10 recipe (Gemini clip, panel by panel). Inputs: GEMINI clip (720x1280, 10.03 s), card.png (CTA card from card.py), mixg.wav (voice+bed mix).
G=/root/.claude/uploads/6fd8d102-d852-578a-aa0a-796b7f4d4fb2/a2da4b3e-gemini_generated_video_8854E44C.mp4
FC="[0:v]split=4[s0][s1][s2][s3];[s0]scale=1080:1920,boxblur=40:8,eq=brightness=-0.15[bg];[s1]trim=0:2.6,setpts=PTS-STARTPTS,crop=720:555:0:0,scale=w='1080*(1+0.05*t/2.6)':h=-2:eval=frame,crop=1080:832,format=yuva420p,fade=t=in:st=0:d=0.12:alpha=1,fade=t=out:st=2.48:d=0.12:alpha=1[A];[s2]trim=2.7:5.75,setpts=PTS-STARTPTS,crop=720:640:0:640,scale=w='1080*(1+0.05*t/3.05)':h=-2:eval=frame,crop=1080:960,format=yuva420p,fade=t=in:st=0:d=0.12:alpha=1,fade=t=out:st=2.93:d=0.12:alpha=1,setpts=PTS+2.7/TB[B];[s3]trim=5.9:10.03,setpts=PTS-STARTPTS,scale=918:1632:flags=lanczos,format=yuva420p,fade=t=in:st=0:d=0.12:alpha=1,setpts=PTS+5.9/TB[C];[bg][A]overlay=0:344:eof_action=pass[b1];[b1][B]overlay=0:280:eof_action=pass[b2];[b2][C]overlay=81:288:eof_action=pass[b3];[1:v]format=rgba,fade=t=in:st=6.1:d=0.35:alpha=1[c];[b3][c]overlay=90:420:eof_action=pass[v]"
ffmpeg -y -i "$G" -loop 1 -t 10.03 -framerate 30 -i card.png -i mixg.wav -filter_complex "$FC" -map "[v]" -map 2:a -t 10.03 -r 30 -c:v libx264 -crf 17 -preset medium -pix_fmt yuv420p -c:a aac -b:a 192k -ar 48000 -ac 2 -movflags +faststart ep91-final10.mp4
